    24  /*
    25   * LLVM fuzzing integration.
    26   */
    27
    28  #include "file.h"
    29
    30  #ifndef lint
    31  FILE_RCSID("@(#)$File: magic_fuzzer.c,v 1.1 2017/04/24 19:41:34 christos Exp $")
    32  #endif  /* lint */
    33
    34  #include "magic.h"
    35  #include <libgen.h>
    36  #include <stdlib.h>
    37  #include <err.h>
    38
    39  int LLVMFuzzerInitialize(int *, char ***);
    40  int LLVMFuzzerTestOneInput(const uint8_t *, size_t);
    41
    42  static magic_t magic;
    43
    44  int
    45  LLVMFuzzerInitialize(int *argc, char ***argv)
    46  {
    47          char dfile[MAXPATHLEN], mfile[MAXPATHLEN];
    48
    49          magic = magic_open(MAGIC_NONE);
    50          if (magic == NULL) {
    51                  warn("magic_open");
    52                  return -1;
    53          }
    54
    55          // Poor man's strlcpy(3), to avoid potentially destructive dirname(3)
    56          snprintf(dfile, sizeof(dfile), "%s", (*argv)[0]);
    57          snprintf(mfile, sizeof(mfile), "%s/magic", dirname(dfile));
    58
    59          if (magic_load(magic, mfile) == -1) {
    60                  warnx("magic_load: %s", magic_error(magic));
    61                  return -1;
    62          }
    63
    64          return 0;
    65  }
    66
    67  int
    68  LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
    69  {
    70          if (size == 0)
    71                  return 0;
    72
    73          magic_buffer(magic, data, size);
    74          return 0;
    75  }
